USE instagallery;
SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

-- Demo enrichment seed: more posts, unique media URLs, and richer comments.
-- Safe to run multiple times. It keeps existing records and updates demo ranges only.

SET FOREIGN_KEY_CHECKS = 0;

-- Make existing seeded media unique. The seed value is based on media id, so repeated image URLs disappear.
UPDATE post_media
SET media_file_url = CONCAT('https://picsum.photos/seed/instagallery-existing-media-', id, '/1200/800'),
    thumbnail_url = CONCAT('https://picsum.photos/seed/instagallery-existing-thumb-', id, '/600/400')
WHERE id <= 564;

